// Apply Sonnet's finalized 87 PFAF entries — 2026-05-25
//
// Input: data/pfaf-v2-finalized.json (generated by Sonnet finalization session)
// Action: merge `knownHazardsLtResolved` (status='ok') into pfaf.json

import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const PFAF_PATH = join(__dirname, '..', 'data', 'pfaf.json')
const FINALIZED_PATH = join(__dirname, '..', 'data', 'pfaf-v2-finalized.json')

if (!existsSync(FINALIZED_PATH)) {
  console.error(`[apply-finalized] File not found: ${FINALIZED_PATH}`)
  console.error(`[apply-finalized] Run Sonnet finalization first (tasks/sonnet-finalize-pfaf-flagged.md)`)
  process.exit(1)
}

console.log('[apply-finalized] loading...')
const final = JSON.parse(readFileSync(FINALIZED_PATH, 'utf-8'))
const d = JSON.parse(readFileSync(PFAF_PATH, 'utf-8'))

let applied = 0
let stillFlagged = 0
const stillFlaggedSamples = []
const patternStats = {}

for (const item of final.resolved || []) {
  const entry = d.results[item.latin]
  if (!entry) continue

  patternStats[item.pattern || 'unknown'] = (patternStats[item.pattern || 'unknown'] || 0) + 1

  if (item.status === 'still-flagged') {
    stillFlagged++
    if (stillFlaggedSamples.length < 10) {
      stillFlaggedSamples.push({ latin: item.latin, note: item.note ?? 'no note' })
    }
    continue
  }

  if (!item.knownHazardsLtResolved) continue

  entry.knownHazardsLt = item.knownHazardsLtResolved
  entry._lthazardsV2 = true
  entry._lthazardsV2Fix = `finalized-${item.pattern || 'unknown'}`
  entry._lthazardsV2At = new Date().toISOString()
  applied++
}

writeFileSync(PFAF_PATH, JSON.stringify(d, null, 2))

console.log('')
console.log('=== APPLY FINALIZED DONE ===')
console.log(`Applied: ${applied}`)
console.log(`Still flagged: ${stillFlagged}`)
console.log('Pattern stats:')
for (const [pat, count] of Object.entries(patternStats)) {
  console.log(`  ${pat}: ${count}`)
}
if (stillFlaggedSamples.length > 0) {
  console.log('Still flagged samples:')
  for (const s of stillFlaggedSamples) console.log(`  • ${s.latin}: ${s.note}`)
}
console.log(`pfaf.json updated.`)
